"deskripsi"></textarea></div><button class="btn">Tambah lokasi</button></form><hr style="border:0;border-top:1px solid var(--line);margin:20px 0"><?php while($r=$locs->fetch_assoc()):?><div class="item"><div class="item-thumb"></div><div class="item-info"><b><?=e($r['nama_lokasi'])?></b><small><?=e($r['keterangan'])?></small></div></div><?php endwhile;?></div></div><?php require __DIR__.'/../includes/footer.php';?>
